window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8e6182d2735db5f7"]={"versions": [{"id": "FIG-8e6182d2735db5f7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Ablaufdiagramm zur zeitlichen Einordnung der zyklischen Hauptfunktion <code>FrNm_MainFunction</code> im Kontext der AUTOSAR Classic FlexRay-Netzwerkmanagement-Architektur (<code>FrNm</code>) relativ zum FlexRay-Kommunikationszyklus (<code>FrIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>FlexRay Cycle N / N+1</strong>: Aufeinanderfolgende statische/dynamische FlexRay-Kommunikationszyklen auf der Zeitachse t.\n</li><li><strong>Frame without NM-PDU</strong> (weißes Rechteck): Reguläre FlexRay-Frames ohne NM-Nutzdaten.\n</li><li><strong>Frame with other NM-PDU (RX)</strong> (hellgrünes Rechteck): Empfangene FlexRay-Frames anderer Netzwerkknoten mit NM-PDUs.\n</li><li><strong>Frame with own NM-PDU (TX)</strong> (signalgrünes Rechteck): Eigener zu sendender FlexRay-Frame mit lokaler NM-PDU.\n</li><li><strong>FlexRay Nm Main Function</strong> (gelber Balken): Ausführungsblock der periodischen Funktion <code>FrNm_MainFunction</code>.\n</li><li><strong>FrIf RX-Time</strong>: Verarbeitungs- und Bereitstellungszeitraum des FlexRay Interface (<code>FrIf</code>) nach Empfang der letzten NM-PDU eines Zyklus.\n</li><li><strong>FrIf TX-Time</strong>: Vorlaufzeit des FlexRay Interface vor dem tatsächlichen Sendezeitpunkt der eigenen NM-PDU.\n</li><li><strong>FrNm MainFunction activation window</strong>: Zulässiges Ausführungsfenster für den Aufruf der <code>FrNm_MainFunction</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Im Verlauf von <strong>FlexRay Cycle N</strong> werden Frames empfangen; darunter befinden sich Frames mit NM-PDUs anderer Knoten (RX) sowie eigene gesendete Frames (TX).\n</li><li>Nach Abschluss des Empfangs aller NM-PDUs des aktuellen Zyklus vergeht die systemspezifische Zeitspanne <strong>FrIf RX-Time</strong>.\n</li><li>Am Endpunkt von FrIf RX-Time liegt der <strong>Point in time where all NM-PDUs of the actual cycle are available</strong>; hier beginnt das <strong>FrNm MainFunction activation window</strong>.\n</li><li>Innerhalb dieses Fensters (welches über die Grenze zwischen FlexRay Cycle N und FlexRay Cycle N+1 hinwegreicht) wird die <strong>FlexRay Nm Main Function</strong> genau einmal ausgeführt, um alle empfangenen NM-PDUs auszuwerten und die eigene Sende-NM-PDU für den Folgezyklus vorzubereiten.\n</li><li>Das Aktivierungsfenster endet am <strong>Point in time where the own NM-PDU must be provided</strong>, welcher exakt um die Vorlaufzeit <strong>FrIf TX-Time</strong> vor dem Slot des eigenen Sende-Frames (<strong>Frame with own NM-PDU (TX)</strong> in FlexRay Cycle N+1) liegt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Echtzeit- und Scheduling-Vorgaben</strong>: Das OS-Scheduling (z. B. Task-Aktivierung via Alarm/Schedule Table) muss sicherstellen, dass <code>FrNm_MainFunction</code> strikt innerhalb des Fensters zwischen Verfügbarkeit aller RX-NM-PDUs und dem spätesten Bereitstellungszeitpunkt für das <code>FrIf</code> ausgeführt wird.\n</li><li><strong>Datenkonsistenz und Zyklusbindung</strong>: Ein vorzeitiger Start vor Ende der <code>FrIf RX-Time</code> führt zu unvollständigen Netzwerkmanagementdaten; ein verspätetes Ende nach Ablauf des Aktivierungsfensters verletzt die Sendekonfiguration des FlexRay-Controllers (<code>FrIf TX-Time</code>), sodass die eigene NM-PDU im Zyklus N+1 nicht mehr rechtzeitig übermittelt werden kann.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-89a101ed3330ee26", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Ablaufdiagramm zur zeitlichen Einordnung der zyklischen Hauptfunktion <code>FrNm_MainFunction</code> im Kontext der AUTOSAR Classic FlexRay-Netzwerkmanagement-Architektur (<code>FrNm</code>) relativ zum FlexRay-Kommunikationszyklus (<code>FrIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>FlexRay Cycle N / N+1</strong>: Aufeinanderfolgende statische/dynamische FlexRay-Kommunikationszyklen auf der Zeitachse t.\n</li><li><strong>Frame without NM-PDU</strong> (weißes Rechteck): Reguläre FlexRay-Frames ohne NM-Nutzdaten.\n</li><li><strong>Frame with other NM-PDU (RX)</strong> (hellgrünes Rechteck): Empfangene FlexRay-Frames anderer Netzwerkknoten mit NM-PDUs.\n</li><li><strong>Frame with own NM-PDU (TX)</strong> (signalgrünes Rechteck): Eigener zu sendender FlexRay-Frame mit lokaler NM-PDU.\n</li><li><strong>FlexRay Nm Main Function</strong> (gelber Balken): Ausführungsblock der periodischen Funktion <code>FrNm_MainFunction</code>.\n</li><li><strong>FrIf RX-Time</strong>: Verarbeitungs- und Bereitstellungszeitraum des FlexRay Interface (<code>FrIf</code>) nach Empfang der letzten NM-PDU eines Zyklus.\n</li><li><strong>FrIf TX-Time</strong>: Vorlaufzeit des FlexRay Interface vor dem tatsächlichen Sendezeitpunkt der eigenen NM-PDU.\n</li><li><strong>FrNm MainFunction activation window</strong>: Zulässiges Ausführungsfenster für den Aufruf der <code>FrNm_MainFunction</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Im Verlauf von <strong>FlexRay Cycle N</strong> werden Frames empfangen; darunter befinden sich Frames mit NM-PDUs anderer Knoten (RX) sowie eigene gesendete Frames (TX).\n</li><li>Nach Abschluss des Empfangs aller NM-PDUs des aktuellen Zyklus vergeht die systemspezifische Zeitspanne <strong>FrIf RX-Time</strong>.\n</li><li>Am Endpunkt von FrIf RX-Time liegt der <strong>Point in time where all NM-PDUs of the actual cycle are available</strong>; hier beginnt das <strong>FrNm MainFunction activation window</strong>.\n</li><li>Innerhalb dieses Fensters (welches über die Grenze zwischen FlexRay Cycle N und FlexRay Cycle N+1 hinwegreicht) wird die <strong>FlexRay Nm Main Function</strong> genau einmal ausgeführt, um alle empfangenen NM-PDUs auszuwerten und die eigene Sende-NM-PDU für den Folgezyklus vorzubereiten.\n</li><li>Das Aktivierungsfenster endet am <strong>Point in time where the own NM-PDU must be provided</strong>, welcher exakt um die Vorlaufzeit <strong>FrIf TX-Time</strong> vor dem Slot des eigenen Sende-Frames (<strong>Frame with own NM-PDU (TX)</strong> in FlexRay Cycle N+1) liegt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Echtzeit- und Scheduling-Vorgaben</strong>: Das OS-Scheduling (z. B. Task-Aktivierung via Alarm/Schedule Table) muss sicherstellen, dass <code>FrNm_MainFunction</code> strikt innerhalb des Fensters zwischen Verfügbarkeit aller RX-NM-PDUs und dem spätesten Bereitstellungszeitpunkt für das <code>FrIf</code> ausgeführt wird.\n</li><li><strong>Datenkonsistenz und Zyklusbindung</strong>: Ein vorzeitiger Start vor Ende der <code>FrIf RX-Time</code> führt zu unvollständigen Netzwerkmanagementdaten; ein verspätetes Ende nach Ablauf des Aktivierungsfensters verletzt die Sendekonfiguration des FlexRay-Controllers (<code>FrIf TX-Time</code>), sodass die eigene NM-PDU im Zyklus N+1 nicht mehr rechtzeitig übermittelt werden kann.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8e6182d2735db5f7", "to": "FIG-89a101ed3330ee26", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
